<script setup lang="ts">
import {money,priceLine} from '#shared/utils/pricing'
const db=useDb(),w=useWorkspace(),route=useRoute(),{error,busy,notice,run}=useAction(),lines=ref<any[]>([]),form=ref<any>({}),preview=ref(false),search=ref(''),products=ref<any[]>([]),dirty=ref(false),requestId=ref('')
const {data:quote,refresh}=await useAsyncData('quote-'+route.params.id,async()=>{const q=check(await db.from('quolyn_quotes').select('*').eq('workspace_id',w.value!.id).eq('id',route.params.id).single());form.value={customer_id:q.customer_id||'',issue_date:q.issue_date,expiry_date:q.expiry_date,notes:q.notes,terms:q.terms};lines.value=check(await db.from('quolyn_quote_lines').select('*').eq('quote_id',q.id).order('position')).map(l=>({...l.data,product_id:l.product_id,enquiry_line_id:l.enquiry_line_id,quantity:l.quantity?.toString()||'',description:l.description,discount_bps:l.data.manual_discount_bps??null,effective_discount_bps:l.data.discount_bps,price_minor:l.price_minor?.toString()||'',tax_bps:l.tax_bps,reviewed:l.reviewed,included:l.included}));dirty.value=false;requestId.value=crypto.randomUUID();return q})
const {data:customers}=await useAsyncData('quote-customers',async()=>check(await db.from('quolyn_customers').select('id,name,discount_bps').eq('workspace_id',w.value!.id)))
const documents=ref<any[]>([])
async function loadDocuments(){documents.value=await $fetch<any[]>('/api/quotes/documents',{query:{id:quote.value!.id}})}
onMounted(()=>loadDocuments().catch(()=>{}))
async function downloadSaved(id:string){await run(async()=>{const r=await $fetch('/api/quotes/download',{method:'POST',body:{id}});window.open(r.url,'_blank','noopener')})}
const locked=computed(()=>['sent','accepted','rejected','expired'].includes(quote.value?.status||''))
async function save(){await run(async()=>{const id=check(await db.rpc('save_quote',{w:w.value!.id,p:{...form.value,id:quote.value!.id,version:quote.value!.version,request_id:requestId.value,enquiry_id:quote.value!.enquiry_id,lines:lines.value}}));if(id!==quote.value!.id){await navigateTo('/quotes/'+id);return}await refresh();notice.value='Quote saved and recalculated. Review the validation results.'})}
async function transition(target:string){await run(async()=>{if(dirty.value)throw new Error('Save your changes before changing status');check(await db.rpc('transition_quote',{w:w.value!.id,q:quote.value!.id,v:quote.value!.version,target}));await refresh();notice.value=`Status recorded as ${target}. No message was sent.`})}
async function find(){await run(async()=>{products.value=check(await db.rpc('search_products',{w:w.value!.id,q:search.value}))})}
function add(p?:any){lines.value.push({product_id:p?.id||null,description:p?.name||'',quantity:'',unit:p?.selling_unit||'each',price_unit:p?.price_unit||'each',price_minor:p?.price_minor?.toString()||'',tax_bps:p?.tax_bps??null,discount_bps:null,included:true,reviewed:false,requirements_resolved:false,billing:'requested'});dirty.value=true;products.value=[]}
async function exportFile(format:string){await run(async()=>{if(dirty.value)throw new Error('Save changes before exporting');const r=await $fetch('/api/quotes/export',{method:'POST',body:{id:quote.value!.id,version:quote.value!.version,format}});window.open(r.url,'_blank','noopener');await loadDocuments();notice.value='Private document generated. Download link expires in 60 seconds.'})}
const unitOptions=await useUnitOptions()
</script>
<template><div v-if="quote"><div class="page-title"><div><div class="eyebrow">QUOTES / {{quote.number}}</div><h1>{{quote.number}} <span class="badge-count">Revision {{quote.revision}}</span></h1><p>Tax-exclusive pricing · {{quote.currency}} · Prices recalculated when saved</p></div><div class="row"><span class="pill" :class="quote.status">{{quote.status}}</span><button class="secondary" @click="preview=!preview">{{preview?'Back to editor':'Customer preview'}}</button></div></div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success">{{notice}}</p><div v-if="locked" class="alert warning">This quotation is preserved. Saving changes creates a new revision that requires review.</div><template v-if="!preview"><div class="panel" @input="dirty=true"><div class="form-grid"><label>Customer<select v-model="form.customer_id" @change="dirty=true"><option value="">Not assigned</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label><div class="form-grid"><label>Issue date<input v-model="form.issue_date" type="date"></label><label>Expiry date<input v-model="form.expiry_date" type="date"></label></div></div></div><div class="row between" style="margin:26px 0 16px"><h2>Quotation lines</h2><button class="link" @click="add()">＋ Manual item</button></div><div class="row" style="margin-bottom:15px"><input v-model="search" aria-label="Find catalogue product" placeholder="Find catalogue product by SKU or name…" style="max-width:400px;margin:0"><button class="secondary" @click="find">Search catalogue</button></div><div v-for="p in products" :key="p.id" class="candidate row between"><span>{{p.name}} · {{money(p.price_minor,p.currency)}} / {{p.price_unit}}</span><button class="link" @click="add(p)">Add to quote →</button></div><article v-for="(l,i) in lines" :key="i" class="line-card" @input="dirty=true" @change="dirty=true"><div class="row between"><span class="line-number">LINE {{i+1}} · {{l.product_id?'CATALOGUE PRODUCT':'MANUAL ITEM'}}</span><button class="link" @click="lines.splice(i,1);dirty=true">Remove</button></div><label>Description<input v-model="l.description" required></label><div class="form-grid"><div class="form-grid"><label>Requested quantity<input v-model="l.quantity" type="number" min="0.000001" step="any" placeholder="Unknown"></label><label>Requested unit<select v-model="l.unit"><option v-for="u in unitOptions" :key="u">{{u}}</option></select></label></div><div class="form-grid"><label>Price (minor units)<input v-model="l.price_minor" type="number" min="0" :disabled="!!l.product_id" placeholder="Unresolved"></label><label>Price unit<input v-model="l.price_unit" :disabled="!!l.product_id"></label></div><label>Billable area<select v-model="l.billing"><option value="requested">Requested coverage</option><option value="delivered">Delivered pack coverage</option></select></label><label>Line discount (basis points)<input v-model="l.discount_bps" type="number" min="0" max="10000" placeholder="Use customer default"></label><label>Price override (minor units)<input v-model="l.override_minor" type="number" min="0" placeholder="Use catalogue price"></label><label>Override reason<input v-model="l.override_reason" placeholder="Required for an override"></label><label>Tax (basis points, 0 is explicit)<input v-model="l.tax_bps" type="number" min="0" max="10000" placeholder="Unknown"></label><div><label><input v-model="l.included" type="checkbox">Include in total (otherwise alternative)</label><label><input v-model="l.requirements_resolved" type="checkbox">Critical requirements resolved</label><label><input v-model="l.reviewed" type="checkbox">I reviewed quantity, units, price and tax</label></div></div><p class="muted" style="font-size:11px">{{l.packs?`${l.packs} packs · ${l.delivered} ${l.coverage_unit} delivered · `:''}}Saved billable quantity: {{l.billable||'Unresolved'}} {{l.price_unit}} · Effective discount: {{l.discount_bps==null?'customer default':l.discount_bps/100+'%'}} · Margin: {{l.margin_minor==null?'unavailable':money(l.margin_minor,quote.currency)}}</p></article><div class="panel" @input="dirty=true"><div class="form-grid"><label>Customer-facing notes<textarea v-model="form.notes"></textarea></label><label>Terms and conditions<textarea v-model="form.terms"></textarea></label></div></div><div class="panel"><h2>Validation</h2><p v-if="dirty" class="alert warning">Unsaved changes. Save to recalculate totals and review checks.</p><div v-for="(issue,i) in quote.validation.errors" :key="i" class="alert error">{{typeof issue==='string'?issue:`Line ${issue.line}: ${issue.issues.join('; ')}`}}</div><p v-for="(warning,i) in quote.validation.warnings" :key="i" class="alert warning">{{warning}}</p><p v-if="!quote.validation.errors?.length" class="alert success">All required review checks passed on the saved quotation.</p><div class="row between"><span class="muted">Saved quotation total</span><h2>{{quote.total_minor==null?'Incomplete — no final total':money(quote.total_minor,quote.currency)}}</h2></div></div></template><div v-else class="customer-preview"><span v-if="['draft','needs review'].includes(quote.status)" class="pill warning">DRAFT — NOT A FINAL QUOTATION</span><div class="row between" style="margin-top:20px"><h1>{{quote.snapshot.distributor.name}}</h1><span>{{quote.number}} · R{{quote.revision}}</span></div><p style="white-space:pre-line">{{quote.snapshot.distributor.address}}</p><hr style="margin:25px 0;border-color:#e3e9ee"><div class="row between"><div><span class="eyebrow">PREPARED FOR</span><h2 style="margin-top:8px">{{quote.snapshot.customer.name||'Customer unresolved'}}</h2><p style="white-space:pre-line">{{quote.snapshot.customer.address}}</p></div><div>Issued {{quote.issue_date}}<br>Valid until {{quote.expiry_date}}</div></div><table><thead><tr><th>DESCRIPTION</th><th>QUANTITY / BASIS</th><th>TOTAL</th></tr></thead><tbody><tr v-for="(l,i) in quote.snapshot.lines" :key="i"><td style="white-space:normal">{{l.description}}<small v-if="!l.included">Alternative — excluded from total</small></td><td>{{l.quantity||'Unresolved'}} {{l.unit}}<small>{{money(l.price_minor,quote.currency)}} / {{l.price_unit}} · {{l.discount_bps/100}}% off</small></td><td>{{money(l.total_minor,quote.currency)}}</td></tr></tbody></table><div class="preview-total">{{quote.total_minor==null?'Incomplete draft — no final total':money(quote.total_minor,quote.currency)}}</div><p style="white-space:pre-line">{{quote.notes}}</p><p class="muted" style="white-space:pre-line">{{quote.terms}}</p><p class="fine">Tax-exclusive pricing. Tax shown in line totals.</p></div><div class="sticky-actions" style="margin-top:25px"><div class="row"><button class="primary" :disabled="busy" @click="save">{{locked?'Save as new revision':'Save & recalculate'}}</button><button v-if="['draft','needs review'].includes(quote.status)" class="secondary" :disabled="busy||dirty||quote.validation.errors.length>0" @click="transition('ready')">Mark ready</button><button v-if="quote.status==='ready'" class="secondary" :disabled="busy||dirty" @click="transition('sent')">Record as sent</button><button v-if="quote.status==='sent'" class="secondary" @click="transition('accepted')">Record accepted</button><button v-if="quote.status==='sent'" class="secondary" @click="transition('rejected')">Record rejected</button><button v-if="['sent','ready'].includes(quote.status)" class="link" @click="transition('expired')">Mark expired</button></div><div class="row"><button class="secondary" :disabled="busy||dirty" @click="exportFile('pdf')">↓ {{['draft','needs review'].includes(quote.status)?'Draft PDF':'PDF'}}</button><button class="secondary" :disabled="busy||dirty" @click="exportFile('csv')">↓ CSV</button></div></div><div class="panel" style="margin-top:25px"><h3>Saved documents</h3><p v-if="!documents.length" class="muted">No exports generated yet.</p><div v-for="d in documents" :key="d.id" class="row between"><span class="muted">{{d.path.endsWith('.pdf')?'PDF':'CSV'}} · saved version {{d.quote_version}} · {{new Date(d.created_at).toLocaleString()}}</span><button class="link" @click="downloadSaved(d.id)">Download saved file ↓</button></div><hr style="margin:20px 0;border-color:#eee"><ActivityLog :entity-id="quote.id" /></div></div></template>
